    </svg>
);
const ResultDisplay: FC<{ title: string; result: string | number; interpretation?: string; className?: string; alertLevel?: 'none' | 'warning' | 'critical' }> = ({ title, result, interpretation, className, alertLevel = 'none' }) => {
