                <FormRow key={q.key}>
                    <Label>{q.label}</Label>
                    <Select value={beck[q.key]} onChange={e => updateBeck(q.key, +e.target.value)}>
                        <option value={0}>Ausente / Leve (0)</option>
                        <option value={1}>Moderado (1)</option>
                        <option value={2}>Intenso (2)</option>
                        <option value={3}>Grave (3)</option>
