                    <Label>{q.label}</Label>
                    <Select value={hamilton[q.key]} onChange={e => updateHamilton(q.key, +e.target.value)}>
                        <option value={0}>0 - Ausente</option>
                        <option value={1}>1 - Leve</option>
                        <option value={2}>2 - Moderado</option>
