                        <h4 className="font-semibold mb-2 text-lg text-blue-800 dark:text-emerald-300">{result.study}</h4>
                        <div className="overflow-x-auto rounded-lg border border-gray-200 dark:border-slate-600">
                            <table className="min-w-full text-xs md:text-sm !border-none !shadow-none !m-0">
                                <thead className="bg-gray-100 dark:bg-slate-700">
                                    <tr>
                                        <th scope="col" className="px-3 py-2 text-left font-semibold !border-b-2 !border-gray-300 dark:!border-slate-500">Parámetro</th>
                                        <th scope="col" className="px-3 py-2 text-left font-semibold !border-b-2 !border-gray-300 dark:!border-slate-500">Resultado</th>
                                        <th scope="col" className="px-3 py-2 text-left font-semibold hidden sm:table-cell !border-b-2 !border-gray-300 dark:!border-slate-500">Unidades</th>
                                        <th scope="col" className="px-3 py-2 text-left font-semibold !border-b-2 !border-gray-300 dark:!border-slate-500">Rango</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-gray-200 dark:divide-slate-600">
                                    {result.components?.map(comp => <tr key={comp.parameter} className={`${comp.isAbnormal ? "bg-red-50 dark:bg-red-900/30" : "odd:bg-white even:bg-gray-50 dark:odd:bg-slate-800 dark:even:bg-slate-800/50"}`}>
                                        <td className="px-3 py-2 !border-b border-gray-200 dark:border-slate-700">{comp.parameter}</td>
                                        <td className={`px-3 py-2 font-semibold !border-b border-gray-200 dark:border-slate-700 ${comp.isAbnormal ? 'text-red-600 dark:text-red-400' : ''}`}>{comp.value}</td>
