            </div>}
            {imagingResults.length > 0 && <div>
                <h3 className="font-bold text-xl mb-3 text-blue-900 dark:text-cyan-300 border-b-2 border-blue-200 dark:border-cyan-800 pb-1 inline-block">Resultados de Imagen</h3>
