                    const extractedText = await extractTextFromPdf(file);

                    if (extractedText) {
                        contentToAnalyze = extractedText;
                        mimeType = 'text/plain';
                    } else {
                        // 2. Fallback: PDF escaneado o imagen dentro de PDF -> OCR con IA
