        const html = document.documentElement;
        const wasDark = html.classList.contains('dark');

        try {
            // Forzar modo claro temporalmente para el PDF para asegurar contraste óptimo
            // Esto asegura letras oscuras sobre fondo blanco
            if (wasDark) {
                html.classList.remove('dark');
