                             >
                                {isGeneratingPdf ? '...' : '🖨️ Descargar PDF'}
                            </button>
                        </div>
                    </div>

                    {/* Contenedor Ref para el PDF. Se asegura width 100% y centrado. */}
                    <div ref={analysisRef} className="w-full mx-auto bg-white dark:bg-slate-900">
